def f(g):
    col=max(range(10),key=lambda c:sum(1 for r in range(10) if g[r][c]!=0))
    lr=[r for r in range(10) if g[r][col]==5]
    # pattern block: consecutive rows below last line row with off-line nonzero
    last=max(lr)
    pat=[]; b=last+1
    while b<10 and any(c!=col and g[b][c]!=0 for c in range(10)):
        pat.append(g[b][:]); b+=1
    h=len(pat)
    # empty line rows (no off-line nonzero) take pattern row (r-pat_top) mod h
    out=[r[:] for r in g]
    if h>0 and lr:
        pt=min([r for r in lr if any(c!=col and g[r][c]!=0 for c in range(10))]) or max(lr)-h+1
        for r in lr:
            if not any(c!=col and g[r][c]!=0 for c in range(10)):
                out[r]=pat[(r-pt)%h]
    return out

